const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const safeUrl=value=>typeof value==='string' && (/^\/(?!\/)[^\s]*$/.test(value)||/^https:\/\/[^\s]+$/.test(value))?value:'#';
function renderBody(value,options={},approvedReview=null,sourceRegistry=sources) {
  const a=typeof value==='string'?articles.find(q=>q.id===value||q.route===value):value;
  if(!a)throw new Error('Unknown editorial article');
  const cite=ids=>ids.length?`<ul class="editorial-evidence" aria-label="Sources for this section">${ids.map(id=>{const s=sourceRegistry[id];if(!s)throw new Error('Unknown source '+id);return`<li><a href="${esc(safeUrl(s.url))}">${esc(s.publisher)}: ${esc(s.title)}</a></li>`}).join('')}</ul>`:'';
  const sections=a.sections.map((s,i)=>`<section id="section-${i+1}"><h2>${esc(s.title)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${s.table?`<div class="editorial-table-scroll" tabindex="0" role="region" aria-label="${esc(s.table.caption)}"><table><caption>${esc(s.table.caption)}</caption><thead><tr>${s.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(r=>`<tr>${r.map((c,j)=>`<${j?'td':'th scope="row"'}>${esc(c)}</${j?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${s.checklist?`<ol>${s.checklist.map(c=>`<li>${esc(c)}</li>`).join('')}</ol>`:''}${cite(s.sourceIds||[])}</section>`).join('');
  const related=(a.relatedArticleIds||[]).map(id=>articles.find(item=>item.id===id)).filter(Boolean);
  const notice=approvedReview?'<aside class="publication-note" role="note"><strong>Human-reviewed revision — awaiting release</strong><p>This review copy is eligible for a separate publication step. No publication date has been assigned and this renderer does not deploy it.</p></aside>':`<aside class="publication-note" role="note"><strong>Research draft — awaiting human editorial review</strong><p>This staging copy is not published or approved for indexing.${a.contentCompletion==='planning_text_complete_recommendation_blocked'?' Its priced build recommendation also needs a verified bill of materials and regional offers.':''}</p></aside>`;
  const attribution=approvedReview?`<p>${esc(approvedReview.byline.name)}: ${esc(approvedReview.byline.attribution)}</p><p>Reviewed by ${esc(approvedReview.review.reviewer.name)} on <time datetime="${esc(approvedReview.review.reviewedAt)}">${esc(approvedReview.review.reviewedAt)}</time>. Sources inspected ${esc(a.evidenceDate)}; no publication date assigned.</p>`:`<p>Prepared by PC Part Performance’s research workflow. Sources inspected ${esc(a.evidenceDate)}; no publication date assigned.</p>`;
  const limitations=(a.limitations||[]).map(l=>approvedReview?l.replace(/\s*(?:Independent human editorial review is still required\.|Human editorial review is pending\.)\s*/gi,' ').trim():l).filter(Boolean);
  return `<article class="program-editorial">${notice}<header><p>${esc(a.category)}</p>${options.includeHeading===false?'':`<h1>${esc(a.title)}</h1>`}<p>${esc(a.description)}</p>${attribution}</header><section class="answer-summary" aria-label="Answer summary"><h2>The answer</h2><p>${esc(a.summary)}</p></section><nav aria-label="On this page"><ul>${a.sections.map((s,i)=>`<li><a href="#section-${i+1}">${esc(s.title)}</a></li>`).join('')}</ul></nav>${sections}<section><h2>Evidence and limits</h2><ul>${limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul>${cite(a.sourceIds)}</section><p><a class="button primary" href="${esc(safeUrl(a.nextAction.url))}">${esc(a.nextAction.label)}</a></p>${(a.relatedTools||[]).length?`<nav aria-label="Related tools"><h2>Useful tools</h2><ul>${a.relatedTools.map(url=>`<li><a href="${esc(safeUrl(url))}">${esc(toolLabels[url]||url)}</a></li>`).join('')}</ul></nav>`:''}${(a.relatedProducts||[]).length?`<nav aria-label="Related hardware"><h2>Hardware in this guide</h2><ul>${a.relatedProducts.map(p=>`<li><a href="${esc(safeUrl(p.url))}">${esc(p.label)}</a></li>`).join('')}</ul></nav>`:''}${related.length?`<nav aria-label="Related reading"><h2>Continue reading</h2><ul>${related.map(item=>`<li><a href="${esc(safeUrl(item.route))}">${esc(item.title)}</a></li>`).join('')}</ul></nav>`:approvedReview?'<p><a href="/blog/">More hardware guides</a></p>':''}</article>`;
}
// This public renderer deliberately remains draft-only, even for an eligible
// copy. Approval does not silently select another mode or publish a date.
function renderArticle(value,options={}){return renderBody(value,options);}
function renderApprovedRevision(value,decision,context,options={}){
  const a=typeof value==='string'?articles.find(q=>q.id===value||q.route===value):value;
  if(!a)throw new Error('Unknown editorial article');
  const review=require('./program-editorial-review.cjs'),resolution=review.resolveReview(a,decision,context);
  if(!resolution.publishable)return{html:null,resolution,published:false,datePublished:null};
  const base=url=>{if(typeof url!=='string'||!/^\/(?!\/)/.test(url))return null;const path=url.split(/[?#]/)[0];return path==='/'?'/':/\.[a-z0-9]+$/i.test(path)?path:path.replace(/\/+$/,'')+'/'};
  if(!Array.isArray(options.availableRoutes))return{html:null,resolution,published:false,datePublished:null,renderIssues:['An actual normal-build route inventory is required to avoid links to withheld drafts.']};
  const available=new Set(options.availableRoutes.map(base).filter(Boolean));
  if(!available.has('/blog/'))return{html:null,resolution,published:false,datePublished:null,renderIssues:['The existing /blog/ fallback must be present in the route inventory.']};
  const visible={...a,
    relatedArticleIds:(a.relatedArticleIds||[]).filter(id=>available.has(base(articles.find(item=>item.id===id)?.route))),
    relatedTools:(a.relatedTools||[]).filter(url=>available.has(base(url))),
    relatedProducts:(a.relatedProducts||[]).filter(product=>available.has(base(product.url))),
    nextAction:available.has(base(a.nextAction?.url))?a.nextAction:{url:'/blog/',label:'Browse hardware guides'}
  };
  return{html:renderBody(visible,options,resolution,context.sources||sources),resolution,published:false,indexable:false,datePublished:null,dateModified:null,renderIssues:[]};
}
function wordCount(a){return[a.title,a.summary,...a.sections.flatMap(s=>[s.title,...s.paragraphs,...(s.table?[s.table.caption,...s.table.headers,...s.table.rows.flat()]:[]),...(s.checklist||[])])].join(' ').trim().split(/\s+/).length;}
function validateEditorial(){
  const failures=[],ids=new Set(),routes=new Set();
  if(articles.length!==40)failures.push('Expected 40 editorial items');
  for(const a of articles){
    if(ids.has(a.id))failures.push('Duplicate ID '+a.id);
    if(routes.has(a.route))failures.push('Duplicate route '+a.route);
    ids.add(a.id);routes.add(a.route);
    if(a.sourceIds.some(id=>!sources[id]))failures.push('Missing source '+a.id);
    if(a.sections.some(s=>(s.sourceIds||[]).some(id=>!sources[id])))failures.push('Missing section source '+a.id);
    if(a.sections.some(s=>(s.sourceIds||[]).some(id=>!a.sourceIds.includes(id))))failures.push('Section source outside article register '+a.id);
    if(a.published||a.publishable||a.indexable||a.datePublished||a.dateModified||a.humanReview||a.reviewStatus!=='needs_human_review')failures.push('Invalid review gate '+a.id);
    if(!a.blockingDependencies.includes('human_editorial_review'))failures.push('Missing independent review dependency '+a.id);
    if(a.sections.length<3||a.sections.some(s=>!s.paragraphs?.length))failures.push('Incomplete body '+a.id);
    if(!a.nextAction?.url||safeUrl(a.nextAction.url)==='#')failures.push('Missing or unsafe next action '+a.id);
    if(a.sections.some(s=>s.table?.rows.some(row=>row.length!==s.table.headers.length)))failures.push('Uneven table '+a.id);
    if(a.relatedArticleIds.some(id=>!articles.some(item=>item.id===id)||id===a.id))failures.push('Invalid related article '+a.id);
    if(a.relatedTools.some(url=>safeUrl(url)==='#'))failures.push('Unsafe tool link '+a.id);
    const html=renderArticle(a);
    if((html.match(/<h1>/g)||[]).length!==1)failures.push('Wrong main-heading count '+a.id);
    if(/<script\b|application\/ld\+json|datePublished/.test(html))failures.push('Draft leaked script or publication markup '+a.id);
    if(!html.includes('awaiting human editorial review'))failures.push('Missing visible draft gate '+a.id);
  }
  for(let i=1;i<=40;i++)if(!ids.has(String(i).padStart(2,'0')))failures.push('Missing editorial item '+i);
  const words=articles.map(wordCount);
  return{evidenceDate,articleCount:articles.length,sourceCount:Object.keys(sources).length,totalWords:words.reduce((a,b)=>a+b,0),minWords:Math.min(...words),maxWords:Math.max(...words),failures,articles:articles.map(a=>({id:a.id,route:a.route,title:a.title,words:wordCount(a),status:a.status,reviewStatus:a.reviewStatus,blockingDependencies:a.blockingDependencies}))};
}
